/*
 * Self-destroying service worker.
 *
 * This file used to be generated by next-pwa. That worker cached RSC payloads
 * and documents, so after each deploy it served stale payloads pointing at
 * build chunks that no longer existed, and client-side navigation to /day and
 * /analytics either hung on its 10s network timeout or failed outright.
 *
 * next-pwa is gone, but browsers that already installed the old worker keep
 * running it until something replaces it. Because this file is byte-different
 * from what they have, the browser's update check installs this one instead,
 * and this one deletes every cache and unregisters itself.
 *
 * Keep this file until you're confident no client is still running the old
 * worker. Deleting it early would make /sw.js 404, which leaves an already
 * installed worker in place rather than removing it.
 */

self.addEventListener('install', () => {
    self.skipWaiting();
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        (async () => {
            const keys = await caches.keys();
            await Promise.all(keys.map((key) => caches.delete(key)));

            await self.registration.unregister();

            // Reload any open tabs so they're served by the network again
            // instead of by this worker.
            const clients = await self.clients.matchAll({ type: 'window' });
            for (const client of clients) {
                client.navigate(client.url);
            }
        })()
    );
});
